const WILL_DC = 32;
const DAMAGE = "2d8[void]";                  // tune the vortex's damage here
const HOLDER_TOKEN_ID = "2ukQ7Yrj5bLzqL7J"; // placeholder anchor that carried the aura — skip it

if (game.user !== game.users.activeGM) return; // the active GM posts each creature's card

const token = event?.data?.token;
const actor = token?.actor;
if (!actor?.isOfType?.("creature")) return;
if (token.id === HOLDER_TOKEN_ID) return;

// Shadow creatures are immune to the Vortex of Souls.
if (actor.traits?.has?.("shadow")) return;

// At most once per creature per combat round (enter + turn-start must not double up).
const combat = game.combat;
if (combat) {
  const stamp = combat.id + ":" + combat.round;
  if (actor.getFlag("world", "vortexOfSoulsStamp") === stamp) return;
  await actor.setFlag("world", "vortexOfSoulsStamp", stamp);
}

// Each creature gets its own card. The speaker is its token, so the basic save's roller:self rolls
// for THIS creature regardless of selection or targeting (targeting modules can't redirect it); the
// @Damage applies to the clicker's own character. Basic save: crit success none, success half,
// failure full + Slowed 1, critical failure double + Slowed 2.
const dmg = "@Damage[" + DAMAGE + "|options:area-damage]";
const negativeHealing = !!actor.system?.attributes?.hp?.negativeHealing;
const content = negativeHealing
  ? "<strong>" + token.name + "</strong> is bathed in the <strong>Vortex of Souls</strong> and is <em>healed</em> by the void energy: " + dmg + " <em>(no save; immune to the slow)</em>."
  : "<strong>" + token.name + "</strong> is caught in the <strong>Vortex of Souls</strong> and takes " + dmg + " (@Check[will|dc:" + WILL_DC + "|basic|roller:self|options:area-effect]). On a failure it is also <strong>Slowed 1</strong> (<strong>Slowed 2</strong> on a critical failure).";

await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ token }), content });

