/*
 * Attune Signet Ring — grant the ring's innate spells to a PC (pf2e v8 / Foundry v14).
 *
 * Equipment can't carry a castable spell in pf2e, so when a player character loots the
 * Signet Ring, select their token and run this. It adds a divine "Signet Ring" innate entry
 * holding Enervation (heightened to 8th, 1/day) and Claim Undead (1/day) — the same casts
 * Veyrin uses. The ring's item DC is 34; a character's innate entry derives its own DC from
 * the chosen ability + proficiency, so adjust the entry if you want a flat 34.
 */

const ENERVATION = "Compendium.pf2e.spells-srd.Item.eexkxcqnkXazsGfK";
const CLAIM_UNDEAD = "Compendium.pf2e.spells-srd.Item.GzN9bG6cKZ96YC6l";
const SOURCE_FLAG = "signet-ring";

const actor = canvas.tokens.controlled[0]?.actor ?? game.user.character;
if (!actor) {
  ui.notifications.warn("Select the character's token (or assign yourself a character) first.");
  return;
}

if (actor.itemTypes.spellcastingEntry.some((e) => e.getFlag("pf2e-netherworld", "source") === SOURCE_FLAG)) {
  ui.notifications.warn(`${actor.name} already carries the Signet Ring spells.`);
  return;
}

const [enervation, claimUndead] = await Promise.all([fromUuid(ENERVATION), fromUuid(CLAIM_UNDEAD)]);
if (!enervation || !claimUndead) {
  ui.notifications.error("Attune Signet Ring: couldn't load the ring's spells — is the pf2e system compendium available?");
  return;
}

const [entry] = await actor.createEmbeddedDocuments("Item", [
  {
    type: "spellcastingEntry",
    name: "Signet Ring",
    system: {
      prepared: { value: "innate" },
      tradition: { value: "divine" },
      ability: { value: "cha" },
      proficiency: { value: 1 },
    },
    flags: { "pf2e-netherworld": { source: SOURCE_FLAG } },
  },
]);

const enervationData = enervation.toObject();
enervationData.system.location = { value: entry.id, heightenedLevel: 8, uses: { value: 1, max: 1 } };

const claimUndeadData = claimUndead.toObject();
claimUndeadData.system.location = { value: entry.id, uses: { value: 1, max: 1 } };

await actor.createEmbeddedDocuments("Item", [enervationData, claimUndeadData]);
ui.notifications.info(`Signet Ring attuned to ${actor.name}: Enervation (8th) and Claim Undead, 1/day each.`);
actor.sheet?.render(true);

/*
 * Link Mirror — bind a Shadow Reflection to the PC it mirrors (pf2e v8.1.2).
 *
 * Stores the PC's actor UUID in the Reflection's "mirrorSource" flag; Mirror
 * Cast then matches that PC by actor id. Run once per Reflection during setup,
 * or any time to fix/change a link.
 *
 * Use: select the Reflection token, TARGET the source PC's token, run this.
 * (No target -> a picker lists the player characters instead.)
 */

const reflection = canvas.tokens.controlled[0]?.actor;
if (!reflection || canvas.tokens.controlled.length !== 1) {
  ui.notifications.warn("Link Mirror: select exactly one Reflection token first.");
  return;
}

let pc = [...game.user.targets].map((t) => t.actor).find((a) => a?.type === "character");

if (!pc) {
  const pcs = game.actors.filter((a) => a.type === "character" && a.hasPlayerOwner);
  if (!pcs.length) {
    ui.notifications.warn("Link Mirror: no player characters found.");
    return;
  }
  const current = reflection.getFlag("pf2e-netherworld", "mirrorSource");
  const options = pcs
    .map((a) => `<option value="${a.uuid}" ${a.uuid === current ? "selected" : ""}>${a.name}</option>`)
    .join("");
  const uuid = await foundry.applications.api.DialogV2.prompt({
    window: { title: `Link ${reflection.name}` },
    content: `<p>Which PC does <b>${reflection.name}</b> mirror?</p>
      <select name="src" style="width:100%">${options}</select>`,
    ok: { label: "Link", callback: (_e, btn) => btn.form.elements.src.value },
  }).catch(() => null);
  if (!uuid) return;
  pc = await fromUuid(uuid);
}

await reflection.setFlag("pf2e-netherworld", "mirrorSource", pc.uuid);
ui.notifications.info(`${reflection.name} now mirrors ${pc.name}.`);

/*
 * Make Shadow — spawn a hostile glass Reflection of a PC (pf2e v8.1.2).
 *
 * Clones the selected player character as a level-2-weaker, hostile `character`
 * actor: adds the shadow trait + glass tint, embeds the Mirror Echo / Shattered
 * Echo / Glass Body / Shatter actions, and auto-links it to its source so Mirror
 * Cast works at once. Filed under the "Shadow Reflections" folder.
 *
 * Use: select the PC token (or assign yourself a character) -> run this macro.
 */

const pc = canvas.tokens.controlled[0]?.actor ?? game.user.character;
const api = game.modules.get("pf2e-netherworld")?.api;
if (!api?.makeShadow) {
  ui.notifications.error("Make Shadow: the Nether World module isn't active.");
  return;
}

const shadow = await api.makeShadow(pc);
if (shadow) {
  ui.notifications.info(`${shadow.name} created.`);
  shadow.sheet.render(true);
}

/*
 * Mirror Cast — Shadow Reflection encounter helper (pf2e v8.1.2)
 *
 * Replays the linked PC's spells FROM the selected Reflection token — same
 * spell, same rank, but at the Reflection's spell DC. Ranks above the
 * Reflection's ceiling (rank 6 at level 12) clamp down (the "highest-rank
 * fallback" of the Mirror Echo gimmick).
 *
 * Window = the partner's casts since the Reflection last acted. The chat log is
 * ordered, and the Reflection posts a card whenever IT acts, so we walk the log
 * backward collecting the partner's spells and stop at the first message the
 * Reflection itself authored — that boundary is the Reflection's previous turn.
 * This is initiative-correct without any round tracking: whatever the partner
 * did since the Reflection last went gets caught, same round or last round.
 *
 * A confirm list (all checked) lets you veto or trim before it fires.
 *
 * Setup: link each Reflection to its PC with the "Link Mirror" macro (stored as
 * the PC's actor UUID, matched by actor id). Unlinked Reflections prompt on use.
 *
 * Use: select the Reflection token -> run this macro.
 */

const { DialogV2 } = foundry.applications.api;

const reflection = canvas.tokens.controlled[0]?.actor;
if (!reflection || canvas.tokens.controlled.length !== 1) {
  ui.notifications.warn("Mirror Cast: select exactly one Reflection token first.");
  return;
}

let sourceUuid = reflection.getFlag("pf2e-netherworld", "mirrorSource");
let sourceActor = sourceUuid ? await fromUuid(sourceUuid) : null;
if (!sourceActor) {
  const pcs = game.actors.filter((a) => a.type === "character" && a.hasPlayerOwner);
  if (!pcs.length) {
    ui.notifications.warn("Mirror Cast: no player characters found to link.");
    return;
  }
  const options = pcs.map((a) => `<option value="${a.uuid}">${a.name}</option>`).join("");
  sourceUuid = await DialogV2.prompt({
    window: { title: `Link ${reflection.name}` },
    content: `<p>Which PC does <b>${reflection.name}</b> mirror?</p>
      <select name="src" style="width:100%">${options}</select>`,
    ok: { label: "Link", callback: (_e, btn) => btn.form.elements.src.value },
  }).catch(() => null);
  if (!sourceUuid) return;
  sourceActor = await fromUuid(sourceUuid);
  await reflection.setFlag("pf2e-netherworld", "mirrorSource", sourceUuid);
}

// Walk back through the ordered log: gather the partner's spell casts, stopping
// at the first message the Reflection authored (its previous turn = the window).
const log = game.messages.contents;
const authorId = (m) =>
  m.speakerActor?.id ?? fromUuidSync(m.flags?.pf2e?.origin?.actor ?? "")?.id ?? null;
const candidates = [];
for (let i = log.length - 1; i >= 0; i--) {
  const m = log[i];
  const author = authorId(m);
  if (author === reflection.id) break;
  if (m.flags?.pf2e?.origin?.type === "spell" && author === sourceActor.id) candidates.unshift(m);
}
if (!candidates.length) {
  ui.notifications.warn(`Mirror Cast: nothing from ${sourceActor.name} to mirror since ${reflection.name} last acted.`);
  return;
}

const rows = candidates
  .map((m) => {
    const o = m.flags.pf2e.origin;
    const sp = fromUuidSync(o.uuid);
    return `<label style="display:block;padding:2px 0">
      <input type="checkbox" name="pick" value="${m.id}" checked>
      ${sp?.name ?? "Spell"} <span style="opacity:.7">(rank ${o.castRank ?? sp?.rank ?? "?"})</span>
    </label>`;
  })
  .join("");
const picks = await DialogV2.prompt({
  window: { title: `${reflection.name} mirrors ${sourceActor.name}` },
  content: `<p>Replay these from <b>${reflection.name}</b>:</p>${rows}`,
  ok: {
    label: "Mirror",
    callback: (_e, btn) => [...btn.form.querySelectorAll("input[name=pick]:checked")].map((i) => i.value),
  },
}).catch(() => null);
if (picks === null) return;

let entry = reflection.itemTypes.spellcastingEntry[0];
if (!entry) {
  const dc = reflection.getFlag("pf2e-netherworld", "mirrorSpellDC") ?? 32;
  [entry] = await reflection.createEmbeddedDocuments("Item", [
    {
      name: "Mirror Casting",
      type: "spellcastingEntry",
      system: {
        ability: { value: "cha" },
        spelldc: { dc, value: dc - 8 },
        tradition: { value: "arcane" },
        prepared: { value: "innate" },
        proficiency: { value: 1 },
        showSlotlessLevels: { value: false },
      },
    },
  ]);
}

const maxRank = Math.max(1, Math.ceil((reflection.level || 12) / 2));
let cast = 0;
for (const id of picks) {
  const m = log.find((x) => x.id === id);
  const o = m?.flags.pf2e.origin;
  if (!o) continue;
  const base = m.flags.pf2e.casting?.embeddedSpell
    ? new CONFIG.Item.documentClass(m.flags.pf2e.casting.embeddedSpell, { parent: reflection })
    : await fromUuid(o.uuid);
  if (!base || base.type !== "spell") continue;
  const castRank = Math.min(o.castRank ?? base.rank, maxRank);
  const clone = base.clone({ "system.location.value": entry.id }, { parent: reflection });
  await clone.toMessage(null, { data: { castRank } });
  cast++;
}

ui.notifications.info(`${reflection.name} mirrored ${cast} spell${cast === 1 ? "" : "s"} from ${sourceActor.name}.`);
